const menu=document.getElementById('menu');const navigation=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');navigation.classList.toggle('open',open)});navigation.querySelectorAll('a,button').forEach(a=>a.addEventListener('click',()=>{navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}));
const departments={medicine:{title:'General Medicine',description:'Medical consultations, diagnosis and treatment for a range of health conditions.'},surgery:{title:'General Surgery',description:'The department offers surgical care including appendectomy, hernia repair and other procedures. Ask the hospital which services are appropriate and available for your visit.'},ent:{title:'Ear, Nose & Throat',description:'Care for ear, nose and throat conditions, including ear and sinus surgical services.'},dental:{title:'Dentistry',description:'A range of dental treatments, with coordination across medical departments for patients with other health conditions.'}};
const deptDialog=document.getElementById('department-dialog');const enquiryDialog=document.getElementById('enquiry-dialog');const select=document.getElementById('department');let chosen='General enquiry';
document.querySelectorAll('[data-department]').forEach(b=>b.addEventListener('click',()=>{const d=departments[b.dataset.department];chosen=d.title;document.getElementById('department-title').textContent=d.title;document.getElementById('department-description').textContent=d.description;deptDialog.showModal()}));
function enquire(department){deptDialog.close();select.value=Array.from(select.options).some(o=>o.value===department)?department:'General enquiry';enquiryDialog.showModal()}
document.querySelectorAll('[data-enquire]').forEach(b=>b.addEventListener('click',()=>enquire(b.dataset.enquire)));document.getElementById('department-enquiry').addEventListener('click',()=>enquire(chosen));document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const date=document.getElementById('date');const today=new Date();date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');document.getElementById('enquiry-form').addEventListener('submit',e=>{e.preventDefault();let message='Hello Goodsam Medical Centre, I would like to enquire about '+select.value+'.';if(date.value){const [y,m,d]=date.value.split('-');message+=' My preferred visit date is '+d+'/'+m+'/'+y+'.'}message+=' Please let me know consultation availability. Thank you.';window.open('https://wa.me/917373731757?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});document.getElementById('year').textContent=String(today.getFullYear());

if('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion-enabled');const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}})},{threshold:0.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el))}
